  "inlineSchema": "// ============================================================\n// SIPPCI V2.1 - SCHEMA CORREGIDO\n// Dirección Nacional de Bomberos - Policía Boliviana\n// ============================================================\n\ngenerator client {\n  provider = \"prisma-client-js\"\n}\n\ndatasource db {\n  provider = \"postgresql\"\n  url      = env(\"DATABASE_URL\")\n}\n\n// ============================================\n// 1. USUARIOS EXTERNOS\n// ============================================\nmodel Usuario {\n  id              Int       @id @default(autoincrement())\n  ci              String    @unique @db.VarChar(20)\n  nombre_completo String    @db.VarChar(200)\n  email           String    @unique @db.VarChar(100)\n  telefono        String    @db.VarChar(20)\n  password_hash   String    @db.VarChar(255)\n  tipo_persona    String    @db.VarChar(20)\n  departamento    String?   @db.VarChar(50)\n  provincia       String?   @db.VarChar(50)\n  municipio       String?   @db.VarChar(50)\n  area            String?   @db.VarChar(50)\n  fecha_registro  DateTime  @default(now())\n  activo          Boolean   @default(true)\n  verificado      Boolean   @default(false)\n  ultimo_acceso   DateTime?\n  role            String?   @default(\"EXTERNO\") @db.VarChar(20)\n  grado           String?   @db.VarChar(50)\n  unidad          String?   @db.VarChar(100)\n  created_at      DateTime  @default(now())\n  updated_at      DateTime  @updatedAt\n\n  // Relaciones simplificadas\n  solicitudes    Solicitud[]\n  codigos        CodigoVerificacion[]\n  notificaciones Notificacion[]\n}\n\n// ============================================\n// 2. EMPRESAS\n// ============================================\nmodel Empresa {\n  id                  Int       @id @default(autoincrement())\n  nit                 String    @unique @db.VarChar(20)\n  razon_social        String    @db.VarChar(200)\n  tipo_empresa        String?   @db.VarChar(50)\n  departamento        String?   @db.VarChar(50)\n  provincia           String?   @db.VarChar(50)\n  municipio           String?   @db.VarChar(50)\n  direccion           String?   @db.Text\n  telefono            String?   @db.VarChar(20)\n  email_institucional String?   @db.VarChar(100)\n  representante_id    Int?\n  estado              String    @default(\"PENDIENTE\") @db.VarChar(20)\n  fecha_registro      DateTime  @default(now())\n  fecha_aprobacion    DateTime?\n  observacion         String?   @db.Text\n  created_at          DateTime  @default(now())\n  updated_at          DateTime  @updatedAt\n\n  solicitudes Solicitud[]\n}\n\n// ============================================\n// 3. CÓDIGOS DE VERIFICACIÓN (OTP)\n// ============================================\nmodel CodigoVerificacion {\n  id          Int       @id @default(autoincrement())\n  usuario_id  Int\n  codigo_hash String    @db.VarChar(255)\n  tipo        String    @db.VarChar(20)\n  intentos    Int       @default(0)\n  expira      DateTime\n  usado       Boolean   @default(false)\n  usado_at    DateTime?\n  created_at  DateTime  @default(now())\n\n  usuario Usuario @relation(fields: [usuario_id], references: [id])\n}\n\n// ============================================\n// 4. MÓDULOS Y SUBMÓDULOS\n// ============================================\nmodel Modulo {\n  id          Int      @id @default(autoincrement())\n  nombre      String   @unique @db.VarChar(50)\n  descripcion String?  @db.Text\n  created_at  DateTime @default(now())\n  updated_at  DateTime @updatedAt\n\n  submodulos Submodulo[]\n}\n\nmodel Submodulo {\n  id           Int      @id @default(autoincrement())\n  modulo_id    Int\n  nombre       String   @db.VarChar(100)\n  descripcion  String?  @db.Text\n  tipo_persona String   @db.VarChar(20)\n  created_at   DateTime @default(now())\n  updated_at   DateTime @updatedAt\n\n  modulo      Modulo      @relation(fields: [modulo_id], references: [id])\n  solicitudes Solicitud[] // ← AGREGAR ESTA LÍNEA\n\n  @@unique([modulo_id, nombre])\n}\n\n// ============================================\n// 5. SOLICITUDES\n// ============================================\nmodel Solicitud {\n  id               Int       @id @default(autoincrement())\n  codigo           String    @unique @db.VarChar(50)\n  usuario_id       Int\n  empresa_id       Int?\n  submodulo_id     Int\n  tipo_persona     String    @db.VarChar(20)\n  estado           String    @default(\"BORRADOR\") @db.VarChar(20)\n  fecha_solicitud  DateTime  @default(now())\n  fecha_envio      DateTime?\n  fecha_aprobacion DateTime?\n  observacion      String?   @db.Text\n  ubicacion        Json?\n  created_at       DateTime  @default(now())\n  updated_at       DateTime  @updatedAt\n\n  usuario   Usuario   @relation(fields: [usuario_id], references: [id])\n  empresa   Empresa?  @relation(fields: [empresa_id], references: [id])\n  submodulo Submodulo @relation(fields: [submodulo_id], references: [id])\n}\n\n// ============================================\n// 6. CERTIFICADOS DE HABILITACIÓN\n// ============================================\nmodel CertificadoHabilitacion {\n  id                Int      @id @default(autoincrement())\n  numero_registro   String   @unique @db.VarChar(50)\n  usuario_id        Int?\n  empresa_id        Int?\n  tipo_persona      String   @db.VarChar(20)\n  codigo_qr         String   @unique @db.VarChar(255)\n  fecha_emision     DateTime\n  fecha_vencimiento DateTime\n  estado            String   @default(\"VIGENTE\") @db.VarChar(20)\n  solicitud_id      Int?\n  es_historico      Boolean  @default(false)\n  created_at        DateTime @default(now())\n  updated_at        DateTime @updatedAt\n}\n\n// ============================================\n// 7. NOTIFICACIONES\n// ============================================\nmodel Notificacion {\n  id         Int      @id @default(autoincrement())\n  usuario_id Int\n  tipo       String   @db.VarChar(20)\n  titulo     String   @db.VarChar(255)\n  mensaje    String   @db.Text\n  leida      Boolean  @default(false)\n  fecha      DateTime @default(now())\n  url_accion String?  @db.VarChar(255)\n  created_at DateTime @default(now())\n  updated_at DateTime @updatedAt\n\n  usuario Usuario @relation(fields: [usuario_id], references: [id])\n\n  @@index([usuario_id, leida])\n}\n",
